#include <stdio.h>
int main(void)
{
    int n, i, is_prime = 1;
    scanf("%d", &n);
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            is_prime = 0;
            break;
        }
    }
    printf(is_prime ? "yes\n" : "no\n");
    return 0;
}

#include <stdio.h>
int main(void)
{
    int n, i, x, max, min;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        if (i == 0) {
            max = x;
            min = x;
        } else {
            if (x > max) max = x;
            if (x < min) min = x;
        }
    }
    printf("%d %d\n", max, min);
    return 0;
}

#include <stdio.h>
int main(void)
{
    int n, i, j, t, a[100];
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

int str_len(const char *s)
{
    int n = 0;
    while (s[n] != '\0')
        n++;
    return n;
}

int main(void)
{
    char s[100];
    scanf("%s", s);
    printf("%d\n", str_len(s));
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void)
{
    char s[100], t;
    int i, n;
    scanf("%s", s);
    n = strlen(s);
    for (i = 0; i < n / 2; i++) {
        t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
    printf("%s\n", s);
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void)
{
    int x, y;
    scanf("%d %d", &x, &y);
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

#include <stdio.h>

long fact(int n)
{
    if (n <= 1)
        return 1;
    return n * fact(n - 1);
}

int main(void)
{
    int n;
    scanf("%d", &n);
    printf("%ld\n", fact(n));
    return 0;
}

#include <stdio.h>

long fib(int n)
{
    if (n == 1 || n == 2)
        return 1;
    return fib(n - 1) + fib(n - 2);
}

int main(void)
{
    int n;
    scanf("%d", &n);
    printf("%ld\n", fib(n));
    return 0;
}

#include <stdio.h>

int sum(int a[], int n)
{
    if (n <= 0)
        return 0;
    return a[n - 1] + sum(a, n - 1);
}

int main(void)
{
    int n, i, a[100];
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    printf("%d\n", sum(a, n));
    return 0;
}

#include <stdio.h>

int gcd(int a, int b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

int main(void)
{
    int a, b;
    scanf("%d %d", &a, &b);
    printf("%d\n", gcd(a, b));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node {
    int v;
    struct node *next;
};

int main(void)
{
    int n, i, x;
    struct node *head = NULL, *p, *q;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        p = (struct node *)malloc(sizeof(struct node));
        if (p == NULL)
            return 1;
        p->v = x;
        p->next = head;
        head = p;
    }
    for (q = head; q != NULL; q = q->next)
        printf("%d ", q->v);
    printf("\n");
    while (head != NULL) {
        p = head;
        head = head->next;
        free(p);
    }
    return 0;
}

